	@Test
	void concurrentRepeatedHitsPreservePublishedResult(@TempDir Path directory) throws Exception {
		try (Fixture fixture = new Fixture(directory, false, 128)) {
			IRI expected = VF.createIRI("urn:snapshot-cache:concurrent");
			long id = fixture.store(expected);
			try (View view = fixture.openView()) {
				Observed input = observe(fixture.values.getLmdbValue(expected), view);
				assertEquals(id, fixture.values.getId(view.snapshot, input.value));
				int firstCapture = input.iriCaptureCalls.get();
				ExecutorService executor = Executors.newFixedThreadPool(4);
				try {
					List<Future<?>> futures = new ArrayList<>();
					for (int i = 0; i < 4; i++) {
						futures.add(executor.submit(() -> {
							for (int call = 0; call < 128; call++) {
								assertEquals(id, fixture.values.getId(view.snapshot, input.value));
							}
							return null;
						}));
					}
					for (Future<?> future : futures) {
						future.get(10, TimeUnit.SECONDS);
					}
				} finally {
					executor.shutdownNow();
					assertTrue(executor.awaitTermination(10, TimeUnit.SECONDS));
				}
				assertEquals(firstCapture, input.iriCaptureCalls.get(),
						"Published IRI hits must reuse namespace/local-name capture while allowing cheap validation");
			}
		}
	}

